/// <summary>
/// MPJ_18994 BYOD comparison
/// Class <c>METBYODCompService</c> populates table
/// </summary>
class METBYODCompService extends SysOperationServiceBase
{
    TableName       tableName;
    METNumOfRecords numOfRecords;
    METMaxRecId     maxRecId;
    DataAreaId      legalEntity;

}

Method.Source:
    /// <summary>
    /// Checks if run in batch or not.
    /// </summary>
    public void processOperation()
    {
        METBYODComp ByodComp;

        delete_from ByodComp;

        this.populateBYODCompTable();
    }

    /// <summary>
    /// All inserts are seperated by appropriate method
    /// </summary>
    public void populateBYODCompTable()
    {
        this.GeneralJournalAccountEntryAllCompanies();
        this.BudgetRegisterEntryAllCompanies();
        this.CustInvoiceJournalLine();
        this.CustomerPaymentJournalLine();
        this.CustTrans();
        this.DisputedInvoicesCrossCompany();
        this.VendInvoiceJournalLine();
        this.VendorInvoiceLine();
        this.VendorPaymentJournalLine();
        this.VendSettlementCrossCompany();
        this.VendTrans();
        this.TaxTrans();
        this.LedgerJournalTrans();

        ///MPJ_23482 BYOD comparison data entity DCP 19/04/2022
        this.AssetJournalV2();
        this.AssetTrans();
        this.ProjForecastCost();
        this.ExpenseJournalLine();
        this.ProjPostedTrans();
        this.PurchPurchaseOrderLineV2();
    }

    /// <summary>
    /// General journal account entry insertion
    /// </summary>
    public void GeneralJournalAccountEntryAllCompanies()
    {
        GeneralJournalAccountEntry  generalJournalAccountEntry;
        GeneralJournalEntry         generalJournalEntry;
        Ledger                      ledger;

        select count(RecVersion), maxof(RecId)
            from generalJournalAccountEntry
                join generalJournalEntry
                    where GeneralJournalEntry.RecId == generalJournalAccountEntry.GeneralJournalEntry
                join ledger
                    where ledger.RecId == GeneralJournalEntry.Ledger;
           
        numOfRecords = generalJournalAccountEntry.RecVersion;
        maxRecId = generalJournalAccountEntry.RecId;

        tableName = tableStr(METGeneralJournalAccountEntryAllCompaniesStaging);
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId);
    }

    /// <summary>
    /// Budget register entry insertion
    /// </summary>
    public void BudgetRegisterEntryAllCompanies()
    {
        BudgetTransactionLine   budgetTransactionLine;
        BudgetTransactionHeader budgetTransactionHeader;
        Ledger                  ledger;

        select count(RecVersion), maxof(RecId)
            from budgetTransactionLine
                join budgetTransactionHeader
                    where budgetTransactionHeader.RecId == budgetTransactionLine.BudgetTransactionHeader
                join ledger
                    where ledger.RecId == budgetTransactionHeader.PrimaryLedger;

        numOfRecords = budgetTransactionLine.RecVersion;
        maxRecId = budgetTransactionLine.RecId;

        tableName = tableStr(METBudgetRegisterEntryAllCompaniesStaging);
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId);
    }

    /// <summary>
    /// Customer invoice journal lines insertion
    /// </summary>
    public void CustInvoiceJournalLine()
    {
        LedgerJournalTrans ledgerJournalTrans;
        LedgerJournalTable ledgerJournalTable;

        select crosscompany count(RecVersion), maxof(RecId)
            from ledgerJournalTrans
                where   ledgerJournalTrans.AccountType              == LedgerJournalACType::Cust
                &&      ledgerJournalTrans.OffsetAccountType        == LedgerJournalACType::Ledger
                &&      ledgerJournalTrans.OffsetLedgerDimension    != 0
                &&      ledgerJournalTrans.Invoice
            join ledgerJournalTable
                where   ledgerJournalTable.JournalNum   == ledgerJournalTrans.JournalNum
                &&      ledgerJournalTable.JournalType  == LedgerJournalType::Daily;

        numOfRecords = ledgerJournalTrans.RecVersion;
        maxRecId = ledgerJournalTrans.RecId;

        tableName = tableStr(METCustInvoiceJournalLineStaging);
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId);
    }

