    /// <summary>
    /// Disputed invoices insertion
    /// </summary>
    public void DisputedInvoicesCrossCompany()
    {
        CustDispute     custDispute;
        CustTrans       custTrans;
        ReasonTableRef  reasonTableRef;

        select crosscompany count(RecVersion), maxof(RecId) 
            from custDispute
                join custTrans
                    where custTrans.RecId == custDispute.CustTrans
                join reasonTableRef
                    where reasonTableRef.RecId == custDispute.ReasonTableRef;

        numOfRecords = custDispute.RecVersion;
        maxRecId = custDispute.RecId;

        tableName = tableStr(METDisputedInvoicesCrossCompanyStaging);
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId);
    }

