    /// <summary>
    /// vendor invoice line insertion
    /// </summary>
    public void VendorInvoiceLine()
    {
        VendInvoiceInfoLine     vendInvoiceInfoLine;
        VendInvoiceInfoTable    vendInvoiceInfoTable;
        VendInvoiceInfoSubTable vendInvoiceInfoSubTable;

        select crosscompany count(RecVersion), maxof(RecId) 
            from vendInvoiceInfoLine
                join vendInvoiceInfoTable
                    where vendInvoiceInfoTable.TableRefId == vendInvoiceInfoLine.TableRefId
                join vendInvoiceInfoSubTable
                    where vendInvoiceInfoSubTable.TableRefId == vendInvoiceInfoLine.TableRefId;

        numOfRecords = vendInvoiceInfoLine.RecVersion;
        maxRecId = vendInvoiceInfoLine.RecId;

        tableName = tableStr(METVendorInvoiceLineStaging);
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId);
    }

