    /// <summary>
    /// Asset journal transactions insertion
    /// MPJ_23482 BYOD comparison data entity DCP 19/04/2022
    /// </summary>
    public void AssetJournalV2()
    {
        LedgerJournalTrans ledgerJournalTrans;
        LedgerJournalTable ledgerJournalTable;

        select crosscompany count(RecVersion)
            from    ledgerJournalTrans
            
            exists join ledgerJournalTable
                where   ledgerJournalTable.JournalNum   == ledgerJournalTrans.JournalNum
                &&      ledgerJournalTable.JournalType  == LedgerJournalType::Assets;

        numOfRecords    = ledgerJournalTrans.RecVersion;

        select crosscompany maxof(RecId)
            from    ledgerJournalTable
                where   ledgerJournalTable.JournalType  == LedgerJournalType::Assets

            exists join ledgerJournalTrans
            where   ledgerJournalTable.JournalNum   == ledgerJournalTrans.JournalNum;
        
        maxRecId        = ledgerJournalTable.RecId;
       
        tableName = tableStr(METAssetJournalV2EntityStaging);
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId);
   
    }

