    /// <summary>
    /// Expense journal line insertion
    /// MPJ_23482 BYOD comparison data entity DCP 19/04/2022
    /// </summary>
    public void ExpenseJournalLine()
    {
        LedgerJournalTable  ledgerJournalTable;
        LedgerJournalTrans  ledgerJournalTrans;
        LedgerJournalTrans_Project ledgerJournalTrans_project;


        select crosscompany count(RecVersion), maxof(RecId)
            from ledgerJournalTrans

            exists join ledgerJournalTrans_project
                where   ledgerJournalTrans_project.RefRecId == ledgerJournalTrans.recid
            
            exists join ledgerJournalTable
                where   ledgerJournalTable.JournalNum   == ledgerJournalTrans.JournalNum
                &&     (ledgerJournalTable.JournalType  == LedgerJournalType::Daily
                    ||  ledgerJournalTable.journaltype  == LedgerJournalType::Cost);

        numOfRecords    = ledgerJournalTrans.RecVersion;
        maxRecId        = ledgerJournalTrans.RecId;
        
        tableName = tableStr(METExpenseJournalLineStaging);
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId);
    }

    /// <summary>
    /// Project posted transactions insertion
    /// MPJ_23482 BYOD comparison data entity DCP 19/04/2022
    /// </summary>
    public void ProjPostedTrans()
    {
        ProjPostedTransTable    projPostedTransTable;
        ProjTable               projTable;
        ProjTransPosting        projTransPosting;

        select crosscompany count(RecVersion), maxof(RecId)
            from projPostedTransTable

            join RecId from projTable
                where   projTable.projId    == projPostedTransTable.ProjId
            
            join RecId from projTransPosting
                where   projTransPosting.transId    == projPostedTransTable.transId;

        numOfRecords    = projPostedTransTable.RecVersion;
        maxRecId        = projPostedTransTable.RecId;

        tableName = tableStr(METProjPostedTransStaging);
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId);
    }

    /// <summary>
    /// Purchase order line insertion
    /// MPJ_23482 BYOD comparison data entity DCP 19/04/2022
    /// </summary>
    public void PurchPurchaseOrderLineV2()
    {
        PurchLine   purchLine;
       
        select crosscompany count(RecVersion), maxof(RecId)
            from purchLine
            where   purchLine.IsDeleted     == NoYes::No
            &&      purchLine.PurchaseType  == PurchaseType::Purch;

        numOfRecords    = purchLine.RecVersion;
        maxRecId        = purchLine.RecId;

        tableName = tableStr(METPurchPurchaseOrderLineV2Staging);
        
        this.insertBYODTable(tableName, numOfRecords, maxRecId);
    }

/// <summary>
/// insertion in BYOD Table insertion
/// </summary>
public void insertBYODTable(TableName _tableName, METNumOfRecords _numOfRecords, METMaxRecId _maxRecID)
{
    METBYODComp metBYODComp;
    ttsbegin;
    metBYODComp.TableName       = _tableName;
    metBYODComp.NumOfRecords    = _numOfRecords;
    metBYODComp.MaxRecId        = _maxRecID;
    metBYODComp.insert();
    ttscommit;
}
